+// Imported till sales: each dish sold uses one portion of its recipe per qty.
+// Already-imported tickets are skipped; imports are all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** Every imported sale line, in id order. */
+export function listSales(store) {
+  return [...(store.data.sales ?? [])].sort((a, b) => a.id - b.id);
+}
+
+/** Records validated sale lines, skipping already-imported tickets; all or nothing. */
+export function recordSales(store, rows) {
+  const existingTickets = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const pending = rows.filter((r) => !existingTickets.has(r.ticket));
+  const remaining = new Map();
+  const plans = pending.map((r) => {
+    const dish = getDish(store, r.dishId);
+    const recipe = getRecipe(store, dish.recipeId);
+    const needs = scaled(recipe, r.qty);
+    for (const n of needs) {
+      const item = getItem(store, n.itemId);
+      const available = remaining.has(n.itemId)
+        ? remaining.get(n.itemId)
+        : Math.round(onHand(store, n.itemId) * 1000) / 1000;
+      if (available < n.qty) {
+        const label = r.where ? `${item.name} (${r.where})` : item.name;
+        throw new AppError("not_enough_stock", { item: label, available, unit: item.unit });
+      }
+      remaining.set(n.itemId, Math.round((available - n.qty) * 1000) / 1000);
+    }
+    return { row: r, needs };
+  });
+  store.data.sales ??= [];
+  const importedTickets = new Set();
+  let dishes = 0;
+  for (const { row, needs } of plans) {
+    for (const n of needs) {
+      if (n.qty > 0) consume(store, n.itemId, n.qty, { at: row.soldAt, ref: `sale:${row.ticket}` });
+    }
+    store.data.sales.push({
+      id: store.nextId("sale"),
+      ticket: row.ticket,
+      soldAt: row.soldAt,
+      dishId: row.dishId,
+      qty: row.qty,
+    });
+    importedTickets.add(row.ticket);
+    dishes += row.qty;
+  }
+  return { tickets: importedTickets.size, dishes };
+}
